"""Generate the SYNTHETIC OpenSky and adsbdb fixtures in this folder.

    .venv/bin/python tests/fixtures/generate_synthetic.py      (from ingest/)

Nothing here is recorded traffic. Aircraft, flights and positions are invented
with simple kinematics (straight-line tracks, fixed climb/cruise/descent
profile) so tests can assert against a known ground truth. Airport coordinates
are real public reference data. icao24 addresses (f000xx) and flight numbers
(99xx) are placeholders and may coincide with real assignments by accident.

Deterministic: no randomness, so re-running reproduces the committed files
byte for byte (tests/test_fixtures.py checks this).
"""
import json
import math
from pathlib import Path

HERE = Path(__file__).parent
DISCLAIMER = ("SYNTHETIC TEST DATA. Not recorded from OpenSky or any real aircraft. "
              "Generated by tests/fixtures/generate_synthetic.py.")

T0 = 1792800000          # arbitrary start, 2026-10-24
POLL_S = 90
DURATION_S = 150 * 60
GS_MS = 230.0            # cruise ground speed, m/s
CRUISE_M = 10_500.0
CLIMB_FRAC, DESCENT_FRAC = 0.2, 0.25
LOST_BELOW_M = 600.0     # coverage floor for the "landing inferred" scenario

AIRPORTS = {  # public reference coordinates
    "ATL": (33.6407, -84.4277), "CLT": (35.2144, -80.9473), "DEN": (39.8561, -104.6737),
    "MDW": (41.7868, -87.7522), "ORD": (41.9742, -87.9073),
}


def _km(a, b):
    (la1, lo1), (la2, lo2) = (map(math.radians, AIRPORTS[a]), map(math.radians, AIRPORTS[b]))
    h = math.sin((la2 - la1) / 2) ** 2 + math.cos(la1) * math.cos(la2) * math.sin((lo2 - lo1) / 2) ** 2
    return 6371 * 2 * math.asin(math.sqrt(h))


def _bearing(a, b):
    (la1, lo1), (la2, lo2) = (map(math.radians, AIRPORTS[a]), map(math.radians, AIRPORTS[b]))
    y = math.sin(lo2 - lo1) * math.cos(la2)
    x = math.cos(la1) * math.sin(la2) - math.sin(la1) * math.cos(la2) * math.cos(lo2 - lo1)
    return (math.degrees(math.atan2(y, x)) + 360) % 360


def flight_time_s(dep, arr):
    return round(_km(dep, arr) * 1000 / GS_MS)


def _sv(icao24, callsign, t, lat, lon, alt, on_ground, gs, track, vrate):
    """OpenSky /states/all state vector (17 fields, metres and m/s)."""
    return [icao24, f"{callsign:<8}", "United States", t, t, round(lon, 4), round(lat, 4),
            None if on_ground else round(alt), on_ground, round(gs, 1), round(track, 1),
            None if on_ground else round(vrate, 1), None, None if on_ground else round(alt + 60),
            "2000", False, 0]


def ground(icao24, callsign, apt, t0, t1):
    lat, lon = AIRPORTS[apt]
    return lambda t: _sv(icao24, callsign, t, lat, lon, 0, True, 0.0, 0.0, 0) if t0 <= t < t1 else None


def airborne(icao24, callsign, dep, arr, t_takeoff, start_frac=0.0, lost_below_m=None, gaps=()):
    """Straight-line flight dep->arr. start_frac > 0 means first seen mid-route."""
    dur = flight_time_s(dep, arr)
    t_start = t_takeoff + start_frac * dur
    (la1, lo1), (la2, lo2), trk = AIRPORTS[dep], AIRPORTS[arr], _bearing(dep, arr)
    climb_s, desc_s = CLIMB_FRAC * dur, DESCENT_FRAC * dur

    def at(t):
        if not (t_start <= t < t_takeoff + dur) or any(g0 <= t < g1 for g0, g1 in gaps):
            return None
        e = t - t_takeoff
        f = e / dur
        if e < climb_s:
            alt, vr = CRUISE_M * e / climb_s, CRUISE_M / climb_s
        elif e > dur - desc_s:
            alt, vr = CRUISE_M * (dur - e) / desc_s, -CRUISE_M / desc_s
        else:
            alt, vr = CRUISE_M, 0.0
        if lost_below_m is not None and vr < 0 and alt < lost_below_m:
            return None
        return _sv(icao24, callsign, t, la1 + (la2 - la1) * f, lo1 + (lo2 - lo1) * f, alt, False, GS_MS, trk, vr)
    return at


def scenario():
    """Aircraft timelines plus the legs a correct inference should find."""
    m = 60
    dal_out = flight_time_s("ATL", "CLT")
    t1 = T0 + 10 * m                      # DAL9901 takeoff ATL
    t2 = t1 + dal_out                     # lands CLT
    t3 = t2 + 45 * m                      # DAL9902 takeoff CLT (45 min turn)
    t4 = t3 + flight_time_s("CLT", "ATL")
    swa_dur = flight_time_s("DEN", "MDW")
    swa_takeoff = T0 - round(0.4 * swa_dur)  # already 40% along at T0
    ual_takeoff = T0 + 60 * m
    gap = (ual_takeoff + 40 * m, ual_takeoff + 50 * m)
    aal_dur = flight_time_s("ORD", "CLT")
    aal_takeoff = T0 - round(0.5 * aal_dur)

    tracks = [
        ground("f00001", "DAL9901", "ATL", T0, t1),
        airborne("f00001", "DAL9901", "ATL", "CLT", t1),
        ground("f00001", "DAL9901", "CLT", t2, t2 + 15 * m),
        ground("f00001", "DAL9902", "CLT", t2 + 15 * m, t3),   # callsign switches at the gate
        airborne("f00001", "DAL9902", "CLT", "ATL", t3),
        ground("f00001", "DAL9902", "ATL", t4, t4 + 10 * m),
        airborne("f00002", "SWA9903", "DEN", "MDW", swa_takeoff, start_frac=(T0 - swa_takeoff) / swa_dur),
        ground("f00002", "SWA9903", "MDW", swa_takeoff + swa_dur, swa_takeoff + swa_dur + 10 * m),
        ground("f00003", "UAL9904", "DEN", T0 + 40 * m, ual_takeoff),
        airborne("f00003", "UAL9904", "DEN", "ORD", ual_takeoff, gaps=[gap]),
        airborne("f00004", "AAL9905", "ORD", "CLT", aal_takeoff,
                 start_frac=(T0 - aal_takeoff) / aal_dur, lost_below_m=LOST_BELOW_M),
    ]
    expected_legs = [
        {"id": 1, "icao24": "f00001", "callsign": "DAL9901", "dep": "ATL", "arr": "CLT",
         "takeoff_t": t1, "landing_t": t2, "takeoff": "observed", "landing": "observed", "prev": None},
        {"id": 2, "icao24": "f00001", "callsign": "DAL9902", "dep": "CLT", "arr": "ATL",
         "takeoff_t": t3, "landing_t": t4, "takeoff": "observed", "landing": "observed", "prev": 1,
         "note": "same airframe, 45 min turn, callsign changed while on the ground"},
        {"id": 3, "icao24": "f00002", "callsign": "SWA9903", "dep": None, "arr": "MDW",
         "takeoff_t": None, "landing_t": swa_takeoff + swa_dur, "takeoff": "not_seen", "landing": "observed",
         "prev": None, "note": "first seen in cruise; departure unknown from positions alone"},
        {"id": 4, "icao24": "f00003", "callsign": "UAL9904", "dep": "DEN", "arr": None,
         "takeoff_t": ual_takeoff, "landing_t": None, "takeoff": "observed", "landing": "not_yet",
         "prev": None, "note": f"10 min coverage gap {gap[0]}..{gap[1]} must not split the leg; still airborne at end"},
        {"id": 5, "icao24": "f00004", "callsign": "AAL9905", "dep": None, "arr": "CLT",
         "takeoff_t": None, "landing_t": aal_takeoff + aal_dur, "takeoff": "not_seen", "landing": "inferred",
         "prev": None, "note": f"lost below {LOST_BELOW_M:.0f} m on final approach; never seen on the ground"},
    ]
    return tracks, expected_legs


def sequence():
    tracks, expected = scenario()
    polls = []
    for t in range(T0, T0 + DURATION_S + 1, POLL_S):
        polls.append({"time": t, "states": [s for f in tracks if (s := f(t)) is not None]})
    return {
        "_synthetic": True,
        "_disclaimer": DISCLAIMER,
        "_note": ("A sequence of filtered /states/all polls 90 s apart. Times in expected_legs are the "
                  "simulated events; inference sees them only at poll resolution, so allow +/- one poll."),
        "expected_legs": expected,
        "polls": polls,
    }


def raw_mixed_poll():
    """One unfiltered poll: airline traffic plus traffic the ingest filter must drop."""
    t = T0
    airline = [s for s in sequence()["polls"][0]["states"]]
    decoys = [
        _sv("f00010", "N999ZZ", t, 39.70, -104.90, 2500, False, 60, 90, 0),     # GA tail-number callsign
        _sv("f00011", "RCH9999", t, 38.80, -76.80, 9000, False, 220, 45, 0),    # military transport callsign
        _sv("ae9999", "UAL9998", t, 38.90, -77.00, 9000, False, 220, 45, 0),    # airline-shaped, military icao24 block
        _sv("f00012", "EJA9997", t, 40.60, -74.10, 11000, False, 230, 270, 0),  # business-jet charter
        _sv("f00013", "", t, 33.90, -118.40, 300, False, 70, 250, 2),           # no callsign
        _sv("f00014", "ZZZ123", t, 41.00, -95.00, 10000, False, 230, 90, 0),    # unknown airline-shaped prefix
    ]
    return {
        "_synthetic": True,
        "_disclaimer": DISCLAIMER,
        "_note": "One UNFILTERED poll for testing filter_states(); decoys are invented, like everything else here.",
        "time": t,
        "states": airline + decoys,
        "expected": {
            "kept_icao24": [s[0] for s in airline],
            "received": len(airline) + len(decoys),
            "unmatched_prefixes": {"RCH": 1, "EJA": 1, "ZZZ": 1},
        },
    }


def adsbdb_route():
    """adsbdb /v0/callsign response shape for the synthetic DAL9901 (ATL->CLT)."""
    def apt(iata, icao, name, city, elev):
        lat, lon = AIRPORTS[iata]
        return {"country_iso_name": "US", "country_name": "United States", "elevation": elev,
                "iata_code": iata, "icao_code": icao, "latitude": lat, "longitude": lon,
                "municipality": city, "name": name}
    return {
        "_synthetic": True,
        "_disclaimer": DISCLAIMER,
        "response": {"flightroute": {
            "callsign": "DAL9901", "callsign_icao": "DAL9901", "callsign_iata": "DL9901",
            "airline": {"name": "Delta Air Lines", "icao": "DAL", "iata": "DL", "country": "United States",
                        "country_iso": "US", "callsign": "DELTA"},
            "origin": apt("ATL", "KATL", "Hartsfield-Jackson Atlanta International Airport", "Atlanta", 1026),
            "destination": apt("CLT", "KCLT", "Charlotte Douglas International Airport", "Charlotte", 748),
        }},
    }


def _dump_sequence(doc):
    """Readable diffs: header pretty-printed, one state vector per line."""
    def poll(p):
        states = ("\n" + ",\n".join("   " + json.dumps(s) for s in p["states"]) + "\n  ") if p["states"] else ""
        return f'  {{"time": {p["time"]}, "states": [{states}]}}'

    head = json.dumps({k: v for k, v in doc.items() if k != "polls"}, indent=1)
    return head[:-2] + ',\n "polls": [\n' + ",\n".join(poll(p) for p in doc["polls"]) + "\n ]\n}\n"


def render():
    """Map of fixture path -> file content."""
    return {
        HERE / "opensky" / "synthetic_sequence.json": _dump_sequence(sequence()),
        HERE / "opensky" / "synthetic_raw_poll.json": json.dumps(raw_mixed_poll(), indent=1) + "\n",
        HERE / "adsbdb" / "synthetic_callsign_DAL9901.json": json.dumps(adsbdb_route(), indent=1) + "\n",
    }


if __name__ == "__main__":
    for path, content in render().items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content)
        print(f"wrote {path.relative_to(HERE.parents[1])}")
